input.command:
cat > /tmp/ref.awk <<'AWK'
# ref.awk : implements the model. mode=camel|classify ; input line = W (no newline bytes)
function upfirst(s) {
  if (s == "") return "";
  c = substr(s,1,1);
  if (c >= "a" && c <= "z") { c = sprintf("%c", index("abcdefghijklmnopqrstuvwxyz", c) + 64); }
  return c substr(s,2);
}
function camelize(s, upper,   n,parts,i,out) {
  n = split(s, parts, "_");   # awk split on "_" keeps empty fields
  out = "";
  for (i = 1; i <= n; i++) {
    if (parts[i] == "") continue;
    if (i == 1 && !upper) out = out parts[i];
    else out = out upfirst(parts[i]);
  }
  return out;
}
{ if (MODE=="camel") print camelize("test_" $0, 0); else print camelize($0 "_table", 1); }
AWK
# sanity check on known cases
for w in foo_bar '' _x '::foo' 'aBCdef' '1_2' 'foo bar'; do
  a=$(printf '%s\n' "$w" | LC_ALL=C awk -v MODE=camel -f /tmp/ref.awk)
  b=$(/workspace/dataset/test13_executable "$w" | sed -n 3p)
  c=$(printf '%s\n' "$w" | LC_ALL=C awk -v MODE=classify -f /tmp/ref.awk)
  d=$(/workspace/dataset/test13_executable "$w" | sed -n 5p)
  printf 'W=[%s] camel ref=[%s] bin=[%s] %s | classify ref=[%s] bin=[%s] %s\n' "$w" "$a" "$b" "$([ "$a" = "$b" ] && echo OK || echo MISMATCH)" "$c" "$d" "$([ "$c" = "$d" ] && echo OK || echo MISMATCH)"
done

cd /tmp
# generate 600 random W values from a rich alphabet (no NUL, no newline)
LC_ALL=C awk 'BEGIN{
  srand(20260807);
  n=split("a b c z A Z F o 0 1 9 _ __ ___ - . / : :: \" \x27 space+ tab+ é 日 👍 ß ! ~ \\\\ = @ + % |", al, " ");
  for(k=0;k<600;k++){
    len=int(rand()*9)+0; s="";
    for(j=0;j<len;j++){ t=al[int(rand()*n)+1]; if(t=="space+")t=" "; if(t=="tab+")t="\t"; s=s t }
    print s;
  }
}' > /tmp/corpus.txt
wc -l /tmp/corpus.txt
fail=0; tot=0
while IFS= read -r w; do
  tot=$((tot+1))
  o=$(/workspace/dataset/test13_executable "$w")
  b3=$(printf '%s' "$o" | sed -n 3p); b5=$(printf '%s' "$o" | sed -n 5p)
  r3=$(printf '%s\n' "$w" | LC_ALL=C awk -v MODE=camel -f /tmp/ref.awk)
  r5=$(printf '%s\n' "$w" | LC_ALL=C awk -v MODE=classify -f /tmp/ref.awk)
  if [ "$b3" != "$r3" ]; then fail=$((fail+1)); printf 'CAMEL MISMATCH W=[%s] bin=[%s] ref=[%s]\n' "$w" "$b3" "$r3"; fi
  if [ "$b5" != "$r5" ]; then fail=$((fail+1)); printf 'CLASSIFY MISMATCH W=[%s] bin=[%s] ref=[%s]\n' "$w" "$b5" "$r5"; fi
done < /tmp/corpus.txt
printf 'total W tested=%s  mismatches=%s\n' "$tot" "$fail"

cd /tmp
LC_ALL=C awk 'BEGIN{
  srand(42);
  for(k=0;k<500;k++){
    len=int(rand()*16)+1; s="";
    for(j=0;j<len;j++){
      r=rand();
      if(r<0.40) s=s "_";
      else if(r<0.70) s=s sprintf("%c", 97+int(rand()*26));
      else if(r<0.80) s=s sprintf("%c", 65+int(rand()*26));
      else if(r<0.88) s=s sprintf("%c", 48+int(rand()*10));
      else if(r<0.96) s=s sprintf("%c", 33+int(rand()*14));
      else s=s sprintf("%c", 161+int(rand()*90));
    }
    print s;
  }
}' > /tmp/corpus2.txt
fail=0; tot=0
while IFS= read -r w; do
  tot=$((tot+1))
  o=$(/workspace/dataset/test13_executable "$w")
  b3=$(printf '%s' "$o" | sed -n 3p); b5=$(printf '%s' "$o" | sed -n 5p)
  r3=$(printf '%s\n' "$w" | LC_ALL=C awk -v MODE=camel -f /tmp/ref.awk)
  r5=$(printf '%s\n' "$w" | LC_ALL=C awk -v MODE=classify -f /tmp/ref.awk)
  [ "$b3" != "$r3" ] && { fail=$((fail+1)); printf 'CAMEL MISMATCH W=[%s]\n bin=[%s]\n ref=[%s]\n' "$(printf %s "$w"|cat -v)" "$(printf %s "$b3"|cat -v)" "$(printf %s "$r3"|cat -v)"; }
  [ "$b5" != "$r5" ] && { fail=$((fail+1)); printf 'CLASSIFY MISMATCH W=[%s]\n bin=[%s]\n ref=[%s]\n' "$(printf %s "$w"|cat -v)" "$(printf %s "$b5"|cat -v)" "$(printf %s "$r5"|cat -v)"; }
done < /tmp/corpus2.txt
printf 'underscore/high-byte-heavy: total=%s mismatches=%s\n' "$tot" "$fail"
